if (riscv_cpu_cfg(env)->ext_smepmp) {
    val |= (env->mseccfg & mask);
    if ((val ^ env->mseccfg) & mask) {
        tlb_flush(env_cpu(env));
    }
} else {
    mask |= MSECCFG_RLB;
    val &= ~(mask);
}

target_ulong mseccfg_csr_read(CPURISCVState *env)
{
    trace_mseccfg_csr_read(env->mhartid, env->mseccfg);
